-- Separate native NOT_A_CHALLENGE world births. No quest rewards or activation.
CREATE TABLE archmonster_spawn_policy_versions (
 policy_version text PRIMARY KEY,policy_contract text NOT NULL CHECK(policy_contract='wakemu.native-count-archmonster-world-birth.v1'),
 cooldown_ms bigint CHECK(cooldown_ms>0),member_count integer NOT NULL CHECK(member_count=1),
 authority text NOT NULL,source_sha256 text NOT NULL CHECK(length(source_sha256)=64)
);
CREATE TABLE archmonster_spawn_active (
 singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),
 policy_version text NOT NULL REFERENCES archmonster_spawn_policy_versions,enabled boolean NOT NULL DEFAULT false
);
CREATE TABLE archmonster_spawn_sources (
 source_key text NOT NULL,scenario_id integer NOT NULL,template_reference integer NOT NULL CHECK(template_reference>0),
 monster_reference integer NOT NULL CHECK(monster_reference>0),native_min_level integer NOT NULL CHECK(native_min_level>0),
 native_max_level integer NOT NULL CHECK(native_max_level>=native_min_level),
 requested_group_count integer NOT NULL CHECK(requested_group_count=1),
 announcement_duration_ms bigint NOT NULL CHECK(announcement_duration_ms=10000),
 participation_criterion text NOT NULL CHECK(participation_criterion='False'),
 blocked_by_membership boolean NOT NULL,catalog_revision text NOT NULL CHECK(length(catalog_revision)=64),
 monsters_sha256 text NOT NULL CHECK(length(monsters_sha256)=64),source_sha256 text NOT NULL CHECK(length(source_sha256)=64),
 provenance jsonb NOT NULL CHECK(jsonb_typeof(provenance)='object'),
 PRIMARY KEY(source_key,scenario_id),UNIQUE(source_key,scenario_id,monster_reference),
 FOREIGN KEY(source_key,scenario_id) REFERENCES environmental_native_scenarios
);
CREATE TABLE archmonster_spawn_memberships (
 source_key text NOT NULL,scenario_id integer NOT NULL,group_id integer NOT NULL,
 original_criterion text NOT NULL,literal_false boolean NOT NULL,
 PRIMARY KEY(source_key,scenario_id,group_id),
 FOREIGN KEY(source_key,scenario_id) REFERENCES archmonster_spawn_sources
);
CREATE TABLE archmonster_spawn_predicates (
 source_key text NOT NULL,scenario_id integer NOT NULL,group_id integer NOT NULL,ordinal integer NOT NULL CHECK(ordinal>=0),
 function_name text NOT NULL CHECK(function_name IN('GetMonsterCountInZone','GetNbMonstersInZone','GetResourceCountInZone')),
 reference integer NOT NULL CHECK(reference>0),comparison text NOT NULL CHECK(comparison IN('<','>')),
 threshold integer NOT NULL CHECK(threshold>=0),
 PRIMARY KEY(source_key,scenario_id,group_id,ordinal),
 FOREIGN KEY(source_key,scenario_id,group_id) REFERENCES archmonster_spawn_memberships
);
CREATE TABLE archmonster_spawn_scopes (
 source_key text NOT NULL,scenario_id integer NOT NULL,map_id integer NOT NULL CHECK(map_id>0),region_id integer NOT NULL CHECK(region_id>0),
 original_locations jsonb NOT NULL CHECK(jsonb_typeof(original_locations)='array' AND jsonb_array_length(original_locations)>0),
 PRIMARY KEY(source_key,scenario_id,map_id,region_id),
 FOREIGN KEY(source_key,scenario_id) REFERENCES archmonster_spawn_sources
);
CREATE TABLE archmonster_spawn_cadences (
 source_key text NOT NULL,scenario_id integer NOT NULL,policy_version text NOT NULL REFERENCES archmonster_spawn_policy_versions,
 cooldown_ms bigint NOT NULL CHECK(cooldown_ms>0),authority_kind text NOT NULL CHECK(authority_kind IN('SOURCE_DERIVED_PUBLIC','DECLARED_WAKEMU')),
 provenance jsonb NOT NULL CHECK(jsonb_typeof(provenance)='object'),
 PRIMARY KEY(source_key,scenario_id,policy_version),
 FOREIGN KEY(source_key,scenario_id) REFERENCES archmonster_spawn_sources
);
CREATE TABLE archmonster_spawn_births (
 spawn_id text PRIMARY KEY CHECK(length(spawn_id)=64),source_key text NOT NULL,scenario_id integer NOT NULL,
 map_id integer NOT NULL,region_id integer NOT NULL,world_instance_id bigint NOT NULL CHECK(world_instance_id>=0),
 epoch_ms bigint NOT NULL CHECK(epoch_ms>=0),policy_version text NOT NULL REFERENCES archmonster_spawn_policy_versions,
 group_id bigint NOT NULL CHECK(group_id>0),monster_id bigint NOT NULL CHECK(monster_id<0),
 monster_reference integer NOT NULL,native_level integer NOT NULL CHECK(native_level>0),
 spawned_at_ms bigint NOT NULL CHECK(spawned_at_ms>=epoch_ms),cooldown_ms bigint NOT NULL CHECK(cooldown_ms>0),
 cooldown_until_ms bigint NOT NULL CHECK(cooldown_until_ms=spawned_at_ms+cooldown_ms),
 UNIQUE(source_key,scenario_id,map_id,region_id,world_instance_id,epoch_ms),
 UNIQUE(map_id,world_instance_id,group_id),UNIQUE(map_id,world_instance_id,monster_id),
 FOREIGN KEY(source_key,scenario_id,map_id,region_id) REFERENCES archmonster_spawn_scopes,
 FOREIGN KEY(source_key,scenario_id,monster_reference) REFERENCES archmonster_spawn_sources(source_key,scenario_id,monster_reference)
);
CREATE INDEX archmonster_spawn_latest_birth ON archmonster_spawn_births(source_key,scenario_id,map_id,region_id,world_instance_id,spawned_at_ms DESC);
CREATE TABLE archmonster_spawn_publications (
 spawn_id text PRIMARY KEY REFERENCES archmonster_spawn_births,
 created_at_ms bigint NOT NULL CHECK(created_at_ms>=0),published_at_ms bigint
);
CREATE FUNCTION archmonster_spawn_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'Frozen archmonster source, cadence or earned birth is immutable'; END $$;
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['archmonster_spawn_policy_versions','archmonster_spawn_sources','archmonster_spawn_memberships',
 'archmonster_spawn_predicates','archmonster_spawn_scopes','archmonster_spawn_cadences','archmonster_spawn_births'] LOOP
 EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION archmonster_spawn_immutable()',
 'immutable_'||t,t);
 END LOOP;
END $$;
CREATE FUNCTION archmonster_spawn_validate_activation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF NEW.enabled AND NOT EXISTS(SELECT 1 FROM archmonster_spawn_policy_versions p
    WHERE p.policy_version=NEW.policy_version AND p.cooldown_ms IS NOT NULL) THEN
  RAISE EXCEPTION 'Archmonster activation requires an explicit versioned fallback cooldown';
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER archmonster_spawn_validate_activation BEFORE INSERT OR UPDATE ON archmonster_spawn_active
 FOR EACH ROW EXECUTE FUNCTION archmonster_spawn_validate_activation();

